<?php get_header(); ?><main class="main"><section class="section"><div class="container"><div class="blog-grid" data-blog-grid><?php if ( have_posts() ) : while ( have_posts() ) : the_post(); ?><article <?php post_class( 'blog-card' ); ?><?php if ( has_post_thumbnail() ) : ?>><a href="<?php the_permalink(); ?>"><?php the_post_thumbnail( 'p313-card', array( 'class' => 'blog-card__img' ) ); ?></a><?php endif; ?><p class="blog-card__meta"><?php echo esc_html( get_the_date() ); ?></p><h2 class="blog-card__title"><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><p><?php echo esc_html( get_the_excerpt() ); ?></p></article><?php endwhile; the_posts_pagination(); else : ?><p>Записей пока нет.</p><?php endif; ?></div></div></section></main><?php get_footer();
